 "content": "def transform(grid):
    out = [row[:] for row in grid]
    anchors = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(anchors) != 2:
        return out

    colored = [(r, c, grid[r][c]) for r, row in enumerate(grid)
               for c in range(len(row)) if grid[r][c] not in (0, 5)]

    # The 5 embedded beside the colored pattern is its source anchor;
    # the isolated 5 marks where to place the translated copy.
    def attachment_score(anchor):
        ar, ac = anchor
        return sum(abs(r-ar) + abs(c-ac) <= 2 for r, c, _ in colored)

    source = max(anchors, key=attachment_score)
    target = anchors[0] if anchors[1] == source else anchors[1]
    dr, dc = target[0] - source[0], target[1] - source[1]

    # Replace the target marker with the translated pattern, preserving source.
    out[target[0]][target[1]] = 0
    for r, c, value in colored:
        rr, cc = r + dr, c + dc
        if 0 <= rr < len(out) and 0 <= cc < len(out[rr]):
            out[rr][cc] = value
    return out
